package com.marinainsaurralde.plango;
import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.TextView;import androidx.activity.EdgeToEdge;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.google.firebase.auth.FirebaseAuth;import com.marinainsaurralde.plango.data.ConsultasRepository;import com.marinainsaurralde.plango.model.ConsultaHistorial;import com.marinainsaurralde.plango.ui.ConsultaAdapter;import java.util.List;
public class HistorialActivity extends AppCompatActivity{private ConsultaAdapter adapter;protected void onCreate(Bundle b){super.onCreate(b);if(FirebaseAuth.getInstance().getCurrentUser()==null){finish();return;}EdgeToEdge.enable(this);setContentView(R.layout.activity_historial);findViewById(R.id.buttonBackHistory).setOnClickListener(v->finish());RecyclerView list=findViewById(R.id.recyclerHistory);list.setLayoutManager(new LinearLayoutManager(this));adapter=new ConsultaAdapter(this::open);list.setAdapter(adapter);load();}private void load(){show(true,false,null);ConsultasRepository.getInstance().cargar(new ConsultasRepository.LoadCallback(){public void onSuccess(List<ConsultaHistorial>c){if(isFinishing())return;adapter.setItems(c);show(false,c.isEmpty(),c.isEmpty()?getString(R.string.history_empty):null);}public void onError(Exception e){if(!isFinishing())show(false,true,getString(R.string.history_error));}});}private void show(boolean loading,boolean state,String text){findViewById(R.id.progressHistory).setVisibility(loading?View.VISIBLE:View.GONE);findViewById(R.id.recyclerHistory).setVisibility(!loading&&!state?View.VISIBLE:View.GONE);TextView s=findViewById(R.id.textHistoryState);s.setVisibility(state?View.VISIBLE:View.GONE);if(text!=null)s.setText(text);}private void open(ConsultaHistorial c){Intent i=new Intent(this,DetalleConsultaActivity.class);i.putExtra(DetalleConsultaActivity.EXTRA,c);startActivity(i);}}
